/**
 * AI credit + monthly report analysis — BFF proxy to Linm.AI.WebService
 */
import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  AiCreditCheckResult,
  AiGenerateAnalyzeRequest,
  AiGenerateAnalyzeResponse,
  AiInsufficientCreditError,
} from './types';

export const MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE =
  'medical-incident-monthly-report';

const BASE = '/medical-incidents/ai';

function getApiBaseUrl(): string {
  return (import.meta.env.VITE_API_URL as string | undefined)?.replace(/\/$/, '') ?? '';
}

function authHeaders(): Record<string, string> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    'X-Timezone': Intl.DateTimeFormat().resolvedOptions().timeZone,
  };
  const token = localStorage.getItem('auth_token');
  if (token) headers.Authorization = `Bearer ${token}`;
  return headers;
}

export const medicalIncidentsAiEndpoint = {
  checkCredits: async (
    featureKey = MEDICAL_INCIDENT_MONTHLY_REPORT_FEATURE,
  ): Promise<AiCreditCheckResult> => {
    const res = await apiClient.get<BffResponse<AiCreditCheckResult>>(
      `${BASE}/credits/check?featureKey=${encodeURIComponent(featureKey)}`,
    );
    return unwrap(res);
  },

  analyzeReport: async (
    body: AiGenerateAnalyzeRequest,
    requestId?: string,
  ): Promise<AiGenerateAnalyzeResponse> => {
    const url = `${getApiBaseUrl()}${BASE}/reports/analyze`;
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        ...authHeaders(),
        ...(requestId ? { 'X-Request-Id': requestId } : {}),
      },
      body: JSON.stringify(body),
    });

    const json = await response.json().catch(() => ({}));

    if (response.status === 402) {
      const err: AiInsufficientCreditError = {
        status: 402,
        message: json?.message ?? 'AI_CREDIT_INSUFFICIENT',
        data: json?.data,
      };
      throw err;
    }

    if (!response.ok) {
      throw new Error(
        json?.error?.toastMessage || json?.message || 'Phân tích AI thất bại',
      );
    }

    const envelope = json as BffResponse<AiGenerateAnalyzeResponse>;
    return unwrap(envelope);
  },
};
