import {
  notificationEndpoint as baseNotificationEndpoint,
  subscriptionEndpoint as baseSubscriptionEndpoint,
  subscriptionService as baseSubscriptionService,
} from '@linm-soft/common-components';
import { isStandalone } from '../../dev/isStandalone';

const emptyPaged = {
  items: [] as never[],
  unreadCount: 0,
  totalCount: 0,
  page: 1,
  pageSize: 20,
};

const standaloneNotificationEndpoint = {
  getNotifications: async () => emptyPaged,
  getUnreadCount: async () => 0,
  markRead: async () => {},
  markAllRead: async () => {},
  deleteNotification: async () => {},
  clearAll: async () => {},
  markReadByEntity: async () => {},
};

export const notificationEndpoint = isStandalone
  ? standaloneNotificationEndpoint
  : baseNotificationEndpoint;

export const subscriptionEndpoint = isStandalone
  ? {
      getSubscription: async () => ({ isMuted: false }),
      updateSubscription: async () => ({ isMuted: false }),
      registerSubscription: async () => ({ isMuted: false }),
    }
  : baseSubscriptionEndpoint;

export const notificationService = notificationEndpoint;
export const subscriptionService = isStandalone ? subscriptionEndpoint : baseSubscriptionService;

export type { SubscriptionStateDto } from '@linm-soft/common-components';
