import React, { useEffect } from 'react';
import { useAppDispatch } from '../store/hooks';
import { setUser } from '../store/slices/authSlice';
import { seedStandaloneAuth, STANDALONE_MOCK_USER } from './mockAuth';

/** Seeds mock auth once when running standalone (no login redirect). */
export const StandaloneAuthBootstrap: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const dispatch = useAppDispatch();

  useEffect(() => {
    seedStandaloneAuth(true);
    dispatch(setUser(STANDALONE_MOCK_USER));
  }, [dispatch]);

  return <>{children}</>;
};
